import React from "react";
import four from './four.png';
import { Container,Row, Col } from "react-bootstrap";
import './Footer.css';







function Footer () {
  return (
    <footer className="bg-dark text-white text-center py-4">
    
    <Container>
        <Row>
        <Col md={4}>
       <div className="text-start">
      <h1 className="heading1 text-white" id='Footerheading1'><img src={four} alt="Foursquare Logo" style={{ width: "100px", height: "60px" }} />Foursquare </h1>
    </div>
    </Col>
     <Col md={4}>
       <div className="">
        
          <a href="https://www.facebook.com/foursquarechurch" target="_blank" rel="noopener noreferrer" className="text-white mx-2">
            Facebook
          </a>
          <a href="https://twitter.com/foursquare" target="_blank" rel="noopener noreferrer" className="text-white mx-2">
            Twitter
          </a>
          <a href="https://www.instagram.com/foursquarechurch/" target="_blank" rel="noopener noreferrer" className="text-white mx-2">
            Instagram
          </a>
        </div>
        </Col>
        </Row>
      </Container>
    </footer>
  );
};

export default Footer;
